import{_ as n,o as r,c as a,a3 as u}from"./chunks/framework.z_KJ15Ep.js";const f=JSON.parse('{"title":"Abitur und Fachhochschulreife bearbeiten","description":"","frontmatter":{},"headers":[],"relativePath":"zeugnisse/sekundarstufen.md","filePath":"zeugnisse/sekundarstufen.md"}'),s={name:"zeugnisse/sekundarstufen.md"};function i(t,e,h,l,d,b){return r(),a("div",null,[...e[0]||(e[0]=[u('<h1 id="abitur-und-fachhochschulreife-bearbeiten" tabindex="-1">Abitur und Fachhochschulreife bearbeiten <a class="header-anchor" href="#abitur-und-fachhochschulreife-bearbeiten" aria-label="Permalink to &quot;Abitur und Fachhochschulreife bearbeiten&quot;">​</a></h1><p>Bearbeiten Sie Zulassung und Abiturprüfung in der vorgesehenen Reihenfolge. Für den schulischen Teil der Fachhochschulreife gibt es ein gesondertes Verfahren.</p><p>Prüfen Sie vor Beginn die <a href="/zeugnisse/pruefungsordnungen.html">Zuordnung der Prüfungsordnung nach Schulform und Kohorte</a>. Die neue APO-GOSt gilt erstmals für Schülerinnen und Schüler, die im Schuljahr 2027/28 die EF besuchen.</p><h2 id="den-abiturablauf-planen" tabindex="-1">Den Abiturablauf planen <a class="header-anchor" href="#den-abiturablauf-planen" aria-label="Permalink to &quot;Den Abiturablauf planen&quot;">​</a></h2><p>Die Anleitung <a href="/zeugnisse/sekundarstufen/komplette-abiturberechnungen-durchfuehren-tutorial.html">Abitur von der Zulassung bis zum Zeugnis bearbeiten</a> führt durch den vollständigen Ablauf. Für die Einzelbearbeitung verwenden Sie <a href="/zeugnisse/sekundarstufen/abitur-schueler.html">den Abitur-Reiter</a>; die <a href="/zeugnisse/sekundarstufen/abitur-gruppenprozesse-abitur.html">Gruppenprozesse</a> verarbeiten eine passende Q2-Auswahl.</p><h2 id="zulassung-und-prufungen-bearbeiten" tabindex="-1">Zulassung und Prüfungen bearbeiten <a class="header-anchor" href="#zulassung-und-prufungen-bearbeiten" aria-label="Permalink to &quot;Zulassung und Prüfungen bearbeiten&quot;">​</a></h2><ol><li><a href="/zeugnisse/sekundarstufen/leistungsdaten-holen-gruppenprozesse-abitur.html">Leistungsdaten für die Abiturberechnung übernehmen</a>.</li><li><a href="/zeugnisse/sekundarstufen/kurse-algorithmisch-markieren-gruppenprozesse-abitur.html">Kurse für die Abiturzulassung algorithmisch markieren</a> und Markierung sowie Belegung prüfen.</li><li><a href="/zeugnisse/sekundarstufen/abitur-zulassung-berechnen-gruppenprozesse-abitur.html">Die Abiturzulassung berechnen</a> als Grundlage der Entscheidung des zentralen Abiturausschusses.</li><li><a href="/zeugnisse/sekundarstufen/pruefungsergebnisse-eingeben-gruppenprozesse-abitur.html">Abiturprüfungsergebnisse gruppenweise eingeben</a> und gegebenenfalls <a href="/zeugnisse/sekundarstufen/mdl-pruefungen-a1-a3-festlegen-gruppenprozesse-abitur.html">mündliche Prüfungen in A1 bis A3 festlegen</a>.</li></ol><p>Das wiederholte Holen oder Berechnen kann vorhandene Daten überschreiben. Beachten Sie die Hinweise beim jeweiligen Prozess und prüfen Sie die Ergebnisse.</p><h2 id="abschließende-angaben-und-ausgaben" tabindex="-1">Abschließende Angaben und Ausgaben <a class="header-anchor" href="#abschließende-angaben-und-ausgaben" aria-label="Permalink to &quot;Abschließende Angaben und Ausgaben&quot;">​</a></h2><ul><li><a href="/zeugnisse/sekundarstufen/zusatzdaten-latinum-eingeben-gruppenprozesse-abitur.html">Latinum, Graecum und Hebraicum eintragen</a>.</li><li><a href="/zeugnisse/sekundarstufen/abitur-jahr-setzen-fuer-statistik-gruppenprozesse-abitur.html">Das Abiturjahr für die Statistik setzen</a> und <a href="/zeugnisse/sekundarstufen/abiturdaten-verwaltung-export.html">Abiturdaten exportieren</a>.</li><li>Zeugnisse und Nachbereitung gemäß dem <a href="/zeugnisse/sekundarstufen/komplette-abiturberechnungen-durchfuehren-tutorial.html">vollständigen Abiturablauf</a> durchführen.</li></ul><h2 id="die-fachhochschulreife-prufen" tabindex="-1">Die Fachhochschulreife prüfen <a class="header-anchor" href="#die-fachhochschulreife-prufen" aria-label="Permalink to &quot;Die Fachhochschulreife prüfen&quot;">​</a></h2><p>Die Anleitung <a href="/schild3/schueler/fhr-schueler.html">Den schulischen Teil der Fachhochschulreife berechnen</a> beschreibt die Einzelbearbeitung, <a href="/schild3/suchen-gruppenprozesse/fachhochschulreife-pruefen-gruppenprozesse-allgemein.html">Die Fachhochschulreife für eine Schülergruppe prüfen</a> die gemeinsame Prüfung. Beide setzen passende Leistungsdaten voraus. Sprachenfolgen, GeR-Niveaus und Feststellungsprüfungen sind unter <a href="/zeugnisse/sprachen.html">Sprachen und Sprachprüfungen</a> eingeordnet.</p>',12)])])}const c=n(s,[["render",i]]);export{f as __pageData,c as default};
